Method.Implementation:
 Set ..Adapter.WebServiceClientClass = "Service.SH2701ServiceSoap"
 $$$TRACE("In GetOutbound271: " _ ..Adapter.WebServiceURL )


 if (pRequest.subscriberID = "")
 {
 	set pRequest.subscriberID = " "
 }
 if (pRequest.patientSsn = "")
 {
 	set pRequest.patientSsn = " "
 }
 $$$TRACE("Inbound Values- subscriberID: " _ pRequest.subscriberID _ ", dateOfBirth:" _ pRequest.dateOfBirth _ ", patientName: " _ pRequest.patientFirstName _ ", " _ pRequest.patientLastName _ ", SSN: " _ pRequest.patientSsn _ ", eligibility Date: " _ pRequest.eligibilityStartDate _ " - " _ pRequest.eligibilityEndDate _ " , serviceType: " _ pRequest.serviceTypeCodes _ ", subscriberFlag: " _ pRequest.subscriberFlag)  
 Try
 {
	 Set tSC = ..Adapter.InvokeMethod("GetOutbound271",.GetOutbound271Result,pRequest.subscriberID,pRequest.dateOfBirth,pRequest.patientFirstName,pRequest.patientLastName,pRequest.patientSsn,pRequest.eligibilityStartDate,pRequest.eligibilityEndDate,pRequest.serviceTypeCodes,pRequest.subscriberFlag)  
	 if ($$$ISERR(tSC)){
		 $$$LOGERROR("InvokeMethod of GetOutbound271 failed: " _ tSC)
		  return tSC
	 }
	 Set tSC = pRequest.NewResponse(.pResponse)  
	 if ($$$ISERR(tSC)){
		 $$$LOGERROR("NewResponse from GetOutbound271 failed: " _ tSC)
		  return tSC
	 }
	 Set pResponse.GetOutbound271Result=$get(GetOutbound271Result)
	 $$$TRACE("Received 271Result for SubscriberId: " _ pResponse.GetOutbound271Result.SubscriberId _ ", ErrorFlag: " _ pResponse.GetOutbound271Result.ErrorFlag)

	 } Catch ex 
	 { 
		      if 1=ex.%IsA("%Exception.SystemException") 
		      {
		        Set status = ##class(IHC.ITF.ITFCOMMON.Utility).FailMsgError(process.%ConfigName,"System exception Name: " _ ex.Name _ ", Location: "_ ex.Location _", ex: " _ ex)
		      }
			  else 
		      {       
		       Set status =  ##class(IHC.ITF.ITFCOMMON.Utility).FailMsgError(process.%ConfigName,"Exception reported while parsing and collecting Interchange level details: " _ "Error code=" _ ex.Code _ ", data=" _ ex.Data _ ", location=" _ ex.Location)  
		      }
	}  
	return $$$OK
